const listAnswersByQuestion = `-- name: ListAnswersByQuestion :many
SELECT id, question_id, content, is_correct, created_at FROM answers
WHERE question_id = $1
ORDER BY created_at
`

func (q *Queries) ListAnswersByQuestion(ctx context.Context, questionID uuid.UUID) ([]Answer, error) {
	rows, err := q.db.QueryContext(ctx, listAnswersByQuestion, questionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Answer
	for rows.Next() {
		var i Answer
		if err := rows.Scan(
			&i.ID,
			&i.QuestionID,
			&i.Content,
			&i.IsCorrect,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

